import { expectStatus, expect, test, USERS } from "../../fixtures";
import { uniqueName } from "../../fixtures";

test.describe("vendor search", () => {
  test(
    "search ignores case and matches part of a name",
    { tag: "@LIF-13" },
    async ({ apiAs }) => {
      // Arrange
      const member = await apiAs("member");
      const name = `Zephyrine Cold Storage ${uniqueName("search")}`;

      const created = await member.post("/api/vendors", {
        data: {
          name,
          category: "logistics",
          contact_email: `${uniqueName("search")}@northwind.test`,
        },
      });
      const vendor = await expectStatus<{ id: string; name: string }>(created, 201);

      // Act
      const response = await member.get("/api/vendors", {
        params: { q: "COLD stor", limit: 100 },
      });

      // Assert
      const page = await expectStatus<{
        items: { id: string; name: string }[];
        total: number;
      }>(response, 200);
      const ids = page.items.map((v) => v.id);
      expect(ids).toContain(vendor.id);
    },
  );
});
